-- Correggi geometrie non valide prodotte dal clipping
UPDATE public.map_sectors
  SET geometry = ST_Multi(ST_CollectionExtract(ST_MakeValid(geometry), 3))
  WHERE service_type = 'd2d'
    AND NOT ST_IsValid(geometry)
    AND municipality_code IN ('108001', '108002', '108003', '108004', '108005', '108006', '108007', '108008', '108009', '108010', '108011', '108012', '108013', '108014', '108015', '108016', '108017', '108018', '108019', '108020', '108021', '108022', '108023', '108024', '108025', '108026', '108027', '108028', '108029', '108030', '108031', '108032', '108033', '108034', '108035', '108036', '108037', '108038', '108039', '108040', '108041', '108042', '108043', '108044', '108045', '108046', '108047', '108048', '108049', '108050', '108051', '108052', '108053', '108054', '108055');

